'use strict';

// MODULES //

var ndarraylike2scalar = require( '@stdlib/ndarray/base/ndarraylike2scalar' );
var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var strided = require( '@stdlib/blas/ext/base/dtriu' ).ndarray;


// MAIN //

/**
* Copies the upper triangular part of a double-precision floating-point matrix `A` to another matrix `B`.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a two-dimensional input ndarray corresponding to `A`.
*     -   a two-dimensional output ndarray corresponding to `B`.
*     -   a zero-dimensional ndarray specifying the diagonal below which to ignore corresponding to `k`.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* var Float64Matrix = require( '@stdlib/ndarray/matrix/float64' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
*
* var A = new Float64Matrix( [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ] );
* var B = new Float64Matrix( [ [ 0.0, 0.0 ], [ 0.0, 0.0 ] ] );
*
* var k = scalar2ndarray( 0, {
*     'dtype': 'generic'
* });
*
* var out = dtriu( [ A, B, k ] );
* // returns <ndarray>[ [ 1.0, 2.0 ], [ 0.0, 4.0 ] ]
*
* var bool = ( out === B );
* // returns true
*/
function dtriu( arrays ) {
	var A;
	var B;
	var k;

	A = arrays[ 0 ];
	B = arrays[ 1 ];
	k = ndarraylike2scalar( arrays[ 2 ] );

	strided( numelDimension( A, 0 ), numelDimension( A, 1 ), k, getData( A ), getStride( A, 0 ), getStride( A, 1 ), getOffset( A ), getData( B ), getStride( B, 0 ), getStride( B, 1 ), getOffset( B ) ); // eslint-disable-line max-len
	return B;
}


// EXPORTS //

module.exports = dtriu;
